import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const source = fs.readFileSync('src/auth.js', 'utf8').replace('export function', 'function');
let calls = 0;
const renewed = { expired: false };
const context = vm.createContext({ fetchSession: () => { calls++; return renewed; } });
vm.runInContext(source, context);
const valid = { expired: false };
assert.equal(context.refresh(valid), valid);
assert.equal(calls, 0);
assert.equal(context.refresh({ expired: true }), renewed);
assert.equal(calls, 1);
console.log('Passed: valid session unchanged; expired session fetched exactly once.');
